// v1.2 - Assign the next RFI number, skip mail already logged, and spot repeat questions
// v1.1 scored wording, spec section and drawing reference together (plain Jaccard missed rewordings).
// v1.2 records the Gmail message id so re-reading the same email cannot log it twice.
const ai = $('Read and Classify the RFI').first().json.output;
const project = $('Get Matched Project').first().json;
const email = $('Loop Over RFI Emails').first().json;
const settings = $('RFI Intake Settings').first().json;
const existing = $input.all().map(i => i.json).filter(r => r.id && r.rfi_number);

const STOP = new Set(['this','that','with','from','have','will','would','could','should','please','question','about','there','their','been','does','what','when','where','which','they','them','your','ours','confirm','advise','provide','regarding','riverside','medical','office','building']);
function tokens(text) {
  const words = String(text || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/);
  return new Set(words.filter(w => w.length > 3 && !STOP.has(w)));
}
// Overlap coefficient: forgiving when one question is much longer than the other
function wordingScore(a, b) {
  if (!a.size || !b.size) return 0;
  let shared = 0;
  for (const t of a) if (b.has(t)) shared++;
  return shared / Math.min(a.size, b.size);
}
function drawings(text) {
  const found = String(text || '').toUpperCase().match(/[A-Z]{1,3}-?[0-9]{2,4}/g) || [];
  return new Set(found.map(d => d.replace(/-/g, '')));
}
function specKey(text) {
  return String(text || '').replace(/[^0-9]/g, '');
}
function sharesAny(a, b) {
  for (const v of a) if (b.has(v)) return true;
  return false;
}

// Same email seen twice (for example after the trigger is reactivated): do not log it again
const sourceMessageId = String(email.id || '');
let alreadyLogged = null;
for (const row of existing) {
  if (sourceMessageId && String(row.source_message_id || '') === sourceMessageId) { alreadyLogged = row; break; }
}

const askTokens = tokens(ai.question);
const askDrawings = drawings([ai.drawing_ref, ai.question].join(' '));
const askSpec = specKey(ai.spec_section);

let best = null;
let bestScore = 0;
for (const row of existing) {
  const answered = ['answered', 'closed'].includes(String(row.status || '').toLowerCase());
  if (!answered || !String(row.answer || '').trim()) continue;
  const wording = wordingScore(askTokens, tokens(row.question));
  const specMatch = askSpec && askSpec === specKey(row.spec_section) ? 1 : 0;
  const drawingMatch = sharesAny(askDrawings, drawings([row.drawing_ref, row.question].join(' '))) ? 1 : 0;
  const score = 0.6 * wording + 0.25 * specMatch + 0.15 * drawingMatch;
  if (score > bestScore) { bestScore = score; best = row; }
}
const threshold = Number(settings.duplicate_threshold) || 0.45;
const isDuplicate = Boolean(best) && bestScore >= threshold;

const responseDays = Number(project.response_days) || 7;
const rfiNumber = project.project_code + '-' + String(existing.length + 1).padStart(3, '0');

return [{
  json: {
    rfi_number: rfiNumber,
    project_code: project.project_code,
    project_name: project.project_name,
    trade: ai.trade || '',
    asked_by_company: ai.asker_company || email.from?.value?.[0]?.name || '',
    asked_by_email: String(ai.asker_email || email.from?.value?.[0]?.address || '').trim().toLowerCase(),
    subject: ai.subject || email.subject || '',
    question: ai.question || '',
    spec_section: ai.spec_section || '',
    drawing_ref: ai.drawing_ref || '',
    status: isDuplicate ? 'duplicate' : 'open',
    date_received: $now.toFormat('yyyy-MM-dd'),
    date_due: $now.plus({ days: responseDays }).toFormat('yyyy-MM-dd'),
    date_answered: isDuplicate ? $now.toFormat('yyyy-MM-dd') : '',
    answer: isDuplicate ? String(best.answer) : '',
    cost_impact: '',
    schedule_impact: '',
    design_team_email: project.design_team_email,
    pm_email: project.pm_email,
    duplicate_of: isDuplicate ? String(best.rfi_number) : '',
    source_message_id: sourceMessageId,
    already_logged: Boolean(alreadyLogged),
    logged_as: alreadyLogged ? String(alreadyLogged.rfi_number) : '',
    is_duplicate: isDuplicate,
    match_score: Math.round(bestScore * 100) / 100,
    response_days: responseDays,
  },
}];

