// v1.0 - Work out how late each open RFI is and what to do about it
// action: chase (due today or just late), escalate (past the escalation window), wait (still inside the window)
const settings = $('Sweep Settings').first().json;
const escalateAfter = Number(settings.escalate_after_days) || 2;
const rows = $input.all().map(i => i.json).filter(r => r.id && r.rfi_number);

return rows.map(function (r) {
  const due = DateTime.fromISO(String(r.date_due || '').slice(0, 10), { zone: $today.zone });
  const daysOverdue = due.isValid ? Math.round($today.diff(due, 'days').days) : 0;
  let action = 'wait';
  if (daysOverdue > escalateAfter) action = 'escalate';
  else if (daysOverdue >= 0) action = 'chase';
  return { json: { ...r, days_overdue: daysOverdue, action } };
});

