// v1.1 - One digest per project: every open RFI with its age, oldest first
const rows = $input.all().map(i => i.json).filter(r => r.id && r.rfi_number);
const byProject = {};
for (const r of rows) {
  const key = r.project_code || 'unassigned';
  if (!byProject[key]) byProject[key] = [];
  byProject[key].push(r);
}

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function lateness(days) {
  if (days <= 0) return 'in time';
  return days === 1 ? '1 day late' : days + ' days late';
}

return Object.keys(byProject).map(function (code) {
  const list = byProject[code].map(function (r) {
    const due = DateTime.fromISO(String(r.date_due || '').slice(0, 10), { zone: $today.zone });
    const overdue = due.isValid ? Math.round($today.diff(due, 'days').days) : 0;
    return { ...r, days_overdue: overdue };
  }).sort(function (a, b) { return b.days_overdue - a.days_overdue; });

  const rowsHtml = list.map(function (r) {
    const late = r.days_overdue > 0;
    return '<tr' + (late ? ' style=background:#ffebee' : '') + '><td>' + esc(r.rfi_number) + '</td><td>' + esc(r.subject) + '</td><td>' + esc(r.trade) + '</td><td>' + esc(r.asked_by_company) + '</td><td>' + esc(r.date_due) + '</td><td>' + lateness(r.days_overdue) + '</td></tr>';
  }).join('');

  return {
    json: {
      project_code: code,
      project_name: list[0].project_name || code,
      pm_email: list[0].pm_email,
      open_count: list.length,
      overdue_count: list.filter(function (r) { return r.days_overdue > 0; }).length,
      digest_html: '<table border=1 cellpadding=6 cellspacing=0 style=border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px><tr style=background:#263238;color:#ffffff><th>RFI</th><th>Subject</th><th>Trade</th><th>Raised by</th><th>Due</th><th>Status</th></tr>' + rowsHtml + '</table>',
    },
  };
});
